const row = $input.first()?.json ?? {};
let state = {};
if (row.state_json) {
  try { state = JSON.parse(row.state_json); }
  catch { throw new Error('Invalid Oura state JSON'); }
}
const isManual = $execution.mode === 'test';
const dueAt = Number(state.nextDueMs ?? 0);
if (!isManual && Number.isFinite(dueAt) && dueAt > Date.now()) return [];
return [{json:{state,isManual}}];

// Independent alerts: 1–5% battery, unresponsive after 2.5h unchanged, reported 0% dead.
const FIVE_THRESHOLD = 5;
const REARM_AT = 15;
const UNRESPONSIVE_AFTER_MS = 150 * 60000;
const MAX_FRESH_AGE_MS = 6 * 3600000;
const now = Date.now();
const s = {...$('Check Next Poll Time').first().json.state};
let alert = 'none', title = '', message = '';
let level = null, ageMinutes = null, readingStatus = 'missing';
function intervalMins(p) {
  if (p > 40) return 480;
  if (p > 30) return 360;
  if (p > 20) return 240;
  if (p > 10) return 120;
  if (p > 7) return 60;
  if (p > 5) return 30;
  return 15;
}
function timestampMs(r) {
  const n = Number(r.timestamp_unix);
  if (Number.isFinite(n) && n > 0) return n < 1e12 ? n * 1000 : n;
  return Date.parse(r.timestamp || '');
}
let pollMins = 60;
const data = $input.first()?.json?.data;
if (Array.isArray(data) && data.length) {
  const latest = data.reduce((a,b)=>timestampMs(a)>=timestampMs(b)?a:b);
  const n = latest.level == null ? NaN : Number(latest.level);
  const measuredAt = timestampMs(latest);
  if (Number.isFinite(n) && n >= 0 && n <= 100 && Number.isFinite(measuredAt)) {
    level = n;
    ageMinutes = Math.round((now-measuredAt)/60000);
    const fresh = measuredAt <= now+5*60000 && now-measuredAt <= MAX_FRESH_AGE_MS;
    const charging = latest.charging === true || latest.in_charger === true;
    readingStatus = fresh ? 'fresh' : 'stale';
    pollMins = fresh ? intervalMins(level) : Math.min(60,intervalMins(level));
    if (level >= REARM_AT && fresh) {
      s.fiveSent = false;
      s.unresponsiveSent = false;
      s.deadSent = false;
      s.criticalLevel = null;
      s.criticalSinceMs = null;
    }
    const critical = n > 0 && n <= FIVE_THRESHOLD;
    if ((charging && fresh) || !critical) {
      s.criticalLevel = null;
      s.criticalSinceMs = null;
    } else if (s.criticalLevel !== level || !Number.isFinite(Number(s.criticalSinceMs)) || Number(s.criticalSinceMs) <= 0) {
      if (fresh) {
        s.criticalLevel = level;
        s.criticalSinceMs = now;
      }
    }
    if (!charging && level === 0 && s.deadSent !== true) {
      alert = 'dead';
      title = 'Oura Ring';
      message = 'Battery dead (0%).';
      s.deadSent = true;
      s.fiveSent = true;
      s.unresponsiveSent = true;
    } else if (!charging && fresh && critical && s.fiveSent !== true) {
      alert = 'low';
      title = 'Oura Ring';
      message = 'Battery: '+level+'%. Charge now.';
      s.fiveSent = true;
    } else if (!charging && critical && s.fiveSent === true && s.unresponsiveSent !== true &&
               Number.isFinite(Number(s.criticalSinceMs)) &&
               now-Number(s.criticalSinceMs) >= UNRESPONSIVE_AFTER_MS) {
      alert = 'unresponsive';
      title = 'Oura Ring';
      message = 'Unresponsive';
      s.unresponsiveSent = true;
    }
  } else readingStatus = 'invalid';
}
s.nextDueMs = now+pollMins*60000;
return [{json:{key:'oura',state_json:JSON.stringify(s),alert,title,message,
  level,age_minutes:ageMinutes,reading_status:readingStatus,next_poll_minutes:pollMins}}];
